mapper.select:
SELECT d.id, d.task_id, d.library_document_id, d.filename, d.content_type,
       d.size_bytes, d.storage_path, d.created_at
FROM task_document d
JOIN task t ON t.id = d.task_id
JOIN project p ON p.id = t.project_id
WHERE d.id = #{id}
  AND t.deleted = 0
  AND (
      p.owner_id = #{ownerId}
      OR EXISTS (
          SELECT 1 FROM project_member pm
          WHERE pm.project_id = p.id AND pm.user_id = #{ownerId}
      )
  )
